  "source": "def investigate(context, acquire):
    rows = []
    sqlite_sequence = 0
    open_transaction = False
    pending_rows = []
    pending_sequence = 0
    for action in context['actions']:
        op = action['op']
        if op == 'put':
            ident = action['id']
            if open_transaction:
                pending_rows.append(ident)
                if ident > pending_sequence:
                    pending_sequence = ident
            else:
                rows.append(ident)
                if ident > sqlite_sequence:
                    sqlite_sequence = ident
        elif op == 'delete':
            ident = action['id']
            if open_transaction:
                if ident in pending_rows:
                    pending_rows.remove(ident)
                elif ident in rows:
                    pending_rows.append(-ident)
            else:
                if ident in rows:
                    rows.remove(ident)
        elif op == 'begin':
            open_transaction = True
            pending_rows = []
            pending_sequence = 0
        elif op == 'commit':
            for ident in pending_rows:
                if ident > 0:
                    rows.append(ident)
                    if ident > sqlite_sequence:
                        sqlite_sequence = ident
                else:
                    absent = -ident
                    if absent in rows:
                        rows.remove(absent)
            if pending_sequence > sqlite_sequence:
                sqlite_sequence = pending_sequence
            open_transaction = False
            pending_rows = []
            pending_sequence = 0
        elif op == 'rollback':
            open_transaction = False
            pending_rows = []
            pending_sequence = 0
    return sqlite_sequence + 1
